const normalizeVideoId = (videoId: string | number): number => {
  const numericId = typeof videoId === 'string' ? parseInt(videoId, 10) : videoId;
  if (isNaN(numericId)) {
    throw new Error(`Invalid videoId: ${videoId}`);
  }
  return numericId;
};
